-- Executed transactionally in the private researchbridge schema by Go startup.
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('student','teacher')),verified BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS verifications(hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS projects(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES users(id),teacher_id BIGINT REFERENCES users(id),title TEXT NOT NULL,area TEXT NOT NULL,abstract TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','changes_requested','rejected')),feedback TEXT NOT NULL DEFAULT '',updated_at BIGINT NOT NULL);

 CREATE TABLE IF NOT EXISTS password_resets(hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS reset_requests(email_hash TEXT PRIMARY KEY,requested_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS researcher_profiles(user_id BIGINT PRIMARY KEY REFERENCES users(id),bio TEXT NOT NULL DEFAULT '',interests TEXT NOT NULL DEFAULT '',expertise TEXT NOT NULL DEFAULT '',notify_requests BIGINT NOT NULL DEFAULT 1,notify_submissions BIGINT NOT NULL DEFAULT 1,notify_meetings BIGINT NOT NULL DEFAULT 1);
 CREATE TABLE IF NOT EXISTS team_members(project_id BIGINT NOT NULL REFERENCES projects(id),user_id BIGINT NOT NULL REFERENCES users(id),PRIMARY KEY(project_id,user_id));
 CREATE TABLE IF NOT EXISTS project_permissions(project_id BIGINT PRIMARY KEY REFERENCES projects(id),teacher_id BIGINT REFERENCES users(id),can_evaluate BIGINT NOT NULL DEFAULT 0,can_extend BIGINT NOT NULL DEFAULT 0);
 CREATE TABLE IF NOT EXISTS workspace_records(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT REFERENCES projects(id),author_id BIGINT NOT NULL REFERENCES users(id),kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',link TEXT NOT NULL DEFAULT '',status TEXT NOT NULL,feedback TEXT NOT NULL DEFAULT '',due_at BIGINT NOT NULL DEFAULT 0,progress BIGINT NOT NULL DEFAULT 0,score BIGINT NOT NULL DEFAULT 0,criteria TEXT NOT NULL DEFAULT '',assignee_id BIGINT REFERENCES users(id),parent_id BIGINT REFERENCES workspace_records(id),updated_at BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS workspace_project ON workspace_records(project_id,kind,updated_at);
 CREATE TABLE IF NOT EXISTS workspace_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,record_id BIGINT NOT NULL REFERENCES workspace_records(id),actor_id BIGINT NOT NULL REFERENCES users(id),snapshot TEXT NOT NULL,created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS workspace_files(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES projects(id),author_id BIGINT NOT NULL REFERENCES users(id),name TEXT NOT NULL,media_type TEXT NOT NULL,data BYTEA NOT NULL,created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS workspace_notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),project_id BIGINT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,message TEXT NOT NULL,read_at BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL);
 
ALTER TABLE users ADD COLUMN IF NOT EXISTS institution TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN IF NOT EXISTS department TEXT NOT NULL DEFAULT '';
ALTER TABLE users ADD COLUMN IF NOT EXISTS academic_year BIGINT NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS semester BIGINT NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_data BYTEA;
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_type TEXT NOT NULL DEFAULT '';